<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use BusinessMapLocator\Migration\{AreaMigrationExecutor,AreaMigrationJournal,AreaMigrationLock,AreaMigrationRevalidator,AreaMigrationStateStore,MigrationSnapshotStore};
final class AreaMigrationTermProvenanceExecutionTest extends TestCase
{
    private string $dir;
    protected function setUp(): void {$this->dir=dirname(__DIR__).'/.term-fixture-'.bin2hex(random_bytes(4));mkdir($this->dir,0777,true);$GLOBALS['bml_test_options']=$GLOBALS['bml_test_term_meta']=$GLOBALS['bml_test_posts']=$GLOBALS['bml_test_post_terms']=[];$city=(object)['term_id'=>1,'name'=>'Minsk','slug'=>'minsk','parent'=>0,'count'=>0];$GLOBALS['bml_test_terms']=['bml_city'=>[1=>$city],'bml_area'=>[]];}
    protected function tearDown(): void {$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $x)$x->isDir()?rmdir($x->getPathname()):unlink($x->getPathname());rmdir($this->dir);}
    public function testCreatesReciprocalMappingAndIsIdempotent(): void {$store=new MigrationSnapshotStore($this->dir.'/snap');$state=new AreaMigrationStateStore();$lock=new AreaMigrationLock();$journal=new AreaMigrationJournal($this->dir.'/journal');$executor=new AreaMigrationExecutor($store,$state,$lock,$journal,new AreaMigrationRevalidator());$snapshot=['schema_version'=>2,'migration'=>'bml_city_to_area_v1','created_at'=>'x','created_by_user_id'=>1,'ownership'=>['site_url'=>'x','plugin_version'=>'x','wp_version'=>'x','php_version'=>'x','created_at'=>'x','created_by_user_id'=>1],'taxonomies'=>['bml_city','bml_area'],'terms'=>['bml_city'=>[['id'=>1,'name'=>'Minsk','slug'=>'minsk','parent'=>0]],'bml_area'=>[]],'locations'=>[],'plan'=>['counts'=>[],'city_decisions'=>[['status'=>'CREATE','city_id'=>1,'planned_area'=>['name'=>'Minsk','slug'=>'minsk','parent'=>0]]],'collision_list'=>[],'ambiguous_list'=>[],'decision_required_list'=>[]]];$path=$store->write($snapshot);$run=$state->create();foreach([AreaMigrationStateStore::INSPECTED,AreaMigrationStateStore::SNAPSHOTTED,AreaMigrationStateStore::SIMULATED,AreaMigrationStateStore::READY] as $next)$run=$state->transition($run['run_id'],$next,$next===AreaMigrationStateStore::SNAPSHOTTED?['snapshot_path'=>$path]:[]);$lock->acquire($run['run_id']);$this->assertSame('TERM_PHASE_COMPLETE',$executor->executeTermPhase($run['run_id'])['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$area=array_values($GLOBALS['bml_test_terms']['bml_area'])[0];$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(1,(int)get_term_meta(1,'_bml_migrated_from_city_term_id',true));$this->assertSame('TERM_PHASE_COMPLETE',$executor->executeTermPhase($run['run_id'])['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertCount(3,$journal->listRunOperations($run['run_id']));}
    public function testCrashAfterAreaCreateResumesWithoutDuplicate(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $point):void{if($point==='AFTER_AREA_CREATED')throw new LogicException('crash');});try{$executor->executeTermPhase($run['run_id']);$this->fail('Expected injected interruption.');}catch(LogicException){$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame('',get_term_meta(1,'_bml_area_term_id',true));}$resume=$this->executor($state,$lock,$journal);$this->assertSame('TERM_PHASE_COMPLETE',$resume->executeTermPhase($run['run_id'])['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));}
    public function testOneSidedCityProvenanceRecoveryWritesOnlyAreaSide(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $p):void{if($p==='AFTER_AREA_CREATED')throw new LogicException('stop');});try{$executor->executeTermPhase($run['run_id']);}catch(LogicException){}update_term_meta(1,'_bml_area_term_id',1);$resume=$this->executor($state,$lock,$journal);$this->assertSame('TERM_PHASE_COMPLETE',$resume->executeTermPhase($run['run_id'])['code']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(1,(int)get_term_meta(1,'_bml_migrated_from_city_term_id',true));$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);}
    public function testOneSidedAreaProvenanceRecoveryWritesOnlyCitySide(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $p):void{if($p==='AFTER_AREA_CREATED')throw new LogicException('stop');});try{$executor->executeTermPhase($run['run_id']);}catch(LogicException){}update_term_meta(1,'_bml_migrated_from_city_term_id',1);$resume=$this->executor($state,$lock,$journal);$this->assertSame('TERM_PHASE_COMPLETE',$resume->executeTermPhase($run['run_id'])['code']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(1,(int)get_term_meta(1,'_bml_migrated_from_city_term_id',true));$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);}
    public function testStartedCityProvenanceRecovers(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $p):void{if($p==='AFTER_CITY_PROVENANCE_WRITTEN')throw new LogicException('stop');});try{$executor->executeTermPhase($run['run_id']);}catch(LogicException){}$resume=$this->executor($state,$lock,$journal);$this->assertSame('TERM_PHASE_COMPLETE',$resume->executeTermPhase($run['run_id'])['code']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(1,(int)get_term_meta(1,'_bml_migrated_from_city_term_id',true));}
    public function testStartedAreaProvenanceRecovers(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $p):void{if($p==='AFTER_AREA_PROVENANCE_WRITTEN')throw new LogicException('stop');});try{$executor->executeTermPhase($run['run_id']);}catch(LogicException){}$resume=$this->executor($state,$lock,$journal);$this->assertSame('TERM_PHASE_COMPLETE',$resume->executeTermPhase($run['run_id'])['code']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(1,(int)get_term_meta(1,'_bml_migrated_from_city_term_id',true));}
    public function testUnownedSlugCollisionBlocksWithoutSuffixOrProvenance(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun();wp_insert_term('Minsk','bml_area',['slug'=>'minsk','parent'=>0]);$result=$executor->executeTermPhase($run['run_id']);$this->assertSame('BLOCKED',$result['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame('',get_term_meta(1,'_bml_area_term_id',true));}
    public function testCityDriftBlocksBeforeAreaCreation(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun();$GLOBALS['bml_test_terms']['bml_city'][1]->name='Changed';$result=$executor->executeTermPhase($run['run_id']);$this->assertFalse($result['eligible']);$this->assertCount(0,$GLOBALS['bml_test_terms']['bml_area']);}
    public function testUnownedNameCollisionBlocksWithoutAdoption(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun();wp_insert_term('Minsk','bml_area',['slug'=>'unrelated','parent'=>0]);$result=$executor->executeTermPhase($run['run_id']);$this->assertSame('BLOCKED',$result['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame('',get_term_meta(1,'_bml_area_term_id',true));}
    public function testConflictingCityProvenanceBlocksBeforeAreaCreation(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun();update_term_meta(1,'_bml_area_term_id',99);$result=$executor->executeTermPhase($run['run_id']);$this->assertSame('BLOCKED',$result['code']);$this->assertCount(0,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame(99,(int)get_term_meta(1,'_bml_area_term_id',true));}
    public function testPartialResumeRefusesWithoutSameRunLock(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun();$GLOBALS['bml_test_options']['bml_area_migration_planning_runs'][$run['run_id']]['state']=AreaMigrationStateStore::PARTIAL;$this->assertTrue($lock->release($run['run_id']));$result=$executor->resumePartialTermPhase($run['run_id']);$this->assertSame('PARTIAL_RESUME_NOT_ALLOWED',$result['code']);$this->assertCount(0,$GLOBALS['bml_test_terms']['bml_area']);}
    public function testConflictingAreaProvenanceBlocksBeforeCityWrite(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $p):void{if($p==='AFTER_AREA_CREATED')throw new LogicException('stop');});try{$executor->executeTermPhase($run['run_id']);}catch(LogicException){}update_term_meta(1,'_bml_migrated_from_city_term_id',99);$result=$this->executor($state,$lock,$journal)->executeTermPhase($run['run_id']);$this->assertSame('BLOCKED',$result['code']);$this->assertSame('',get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(99,(int)get_term_meta(1,'_bml_migrated_from_city_term_id',true));}
    public function testMaterialAreaDriftBlocksWithoutReplacement(): void {[$state,$lock,$journal,$run,$executor]=$this->fixtureRun(static function(string $p):void{if($p==='AFTER_AREA_CREATED')throw new LogicException('stop');});try{$executor->executeTermPhase($run['run_id']);}catch(LogicException){}$GLOBALS['bml_test_terms']['bml_area'][1]->slug='changed';$result=$this->executor($state,$lock,$journal)->executeTermPhase($run['run_id']);$this->assertSame('BLOCKED',$result['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame('changed',$GLOBALS['bml_test_terms']['bml_area'][1]->slug);}
    public function testPartialMultiCityBatchPreservesCompletedFirstCity(): void {$city2=(object)['term_id'=>2,'name'=>'Brest','slug'=>'brest','parent'=>0,'count'=>0];$GLOBALS['bml_test_terms']['bml_city'][2]=$city2;$store=new MigrationSnapshotStore($this->dir.'/multi');$state=new AreaMigrationStateStore();$lock=new AreaMigrationLock();$journal=new AreaMigrationJournal($this->dir.'/multi-journal');$snapshot=['schema_version'=>2,'migration'=>'bml_city_to_area_v1','created_at'=>'x','created_by_user_id'=>1,'ownership'=>['site_url'=>'x','plugin_version'=>'x','wp_version'=>'x','php_version'=>'x','created_at'=>'x','created_by_user_id'=>1],'taxonomies'=>['bml_city','bml_area'],'terms'=>['bml_city'=>[['id'=>1,'name'=>'Minsk','slug'=>'minsk','parent'=>0],['id'=>2,'name'=>'Brest','slug'=>'brest','parent'=>0]],'bml_area'=>[]],'locations'=>[],'plan'=>['counts'=>[],'city_decisions'=>[['status'=>'CREATE','city_id'=>1,'planned_area'=>['name'=>'Minsk','slug'=>'minsk','parent'=>0]],['status'=>'CREATE','city_id'=>2,'planned_area'=>['name'=>'Brest','slug'=>'brest','parent'=>0]]],'collision_list'=>[],'ambiguous_list'=>[],'decision_required_list'=>[]]];$path=$store->write($snapshot);$run=$state->create();foreach([AreaMigrationStateStore::INSPECTED,AreaMigrationStateStore::SNAPSHOTTED,AreaMigrationStateStore::SIMULATED,AreaMigrationStateStore::READY]as $next)$run=$state->transition($run['run_id'],$next,$next===AreaMigrationStateStore::SNAPSHOTTED?['snapshot_path'=>$path]:[]);$lock->acquire($run['run_id']);update_term_meta(2,'_bml_area_term_id',99);$executor=new AreaMigrationExecutor($store,$state,$lock,$journal,new AreaMigrationRevalidator());$result=$executor->executeTermPhase($run['run_id']);$this->assertSame('PARTIAL',$result['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame('PARTIAL',$executor->resumePartialTermPhase($run['run_id'])['code']);$this->assertCount(1,$GLOBALS['bml_test_terms']['bml_area']);unset($GLOBALS['bml_test_term_meta'][2]['_bml_area_term_id']);$this->assertSame('TERM_PHASE_COMPLETE',$executor->resumePartialTermPhase($run['run_id'])['code']);$this->assertCount(2,$GLOBALS['bml_test_terms']['bml_area']);$this->assertSame(1,(int)get_term_meta(1,'_bml_area_term_id',true));$this->assertSame(2,(int)get_term_meta(2,'_bml_area_term_id',true));}
    /** @return array{0:AreaMigrationStateStore,1:AreaMigrationLock,2:AreaMigrationJournal,3:array<string,mixed>,4:AreaMigrationExecutor} */ private function fixtureRun(?callable $injector=null): array {$store=new MigrationSnapshotStore($this->dir.'/snap-'.bin2hex(random_bytes(2)));$state=new AreaMigrationStateStore();$lock=new AreaMigrationLock();$journal=new AreaMigrationJournal($this->dir.'/journal-'.bin2hex(random_bytes(2)));$snapshot=['schema_version'=>2,'migration'=>'bml_city_to_area_v1','created_at'=>'x','created_by_user_id'=>1,'ownership'=>['site_url'=>'x','plugin_version'=>'x','wp_version'=>'x','php_version'=>'x','created_at'=>'x','created_by_user_id'=>1],'taxonomies'=>['bml_city','bml_area'],'terms'=>['bml_city'=>[['id'=>1,'name'=>'Minsk','slug'=>'minsk','parent'=>0]],'bml_area'=>[]],'locations'=>[],'plan'=>['counts'=>[],'city_decisions'=>[['status'=>'CREATE','city_id'=>1,'planned_area'=>['name'=>'Minsk','slug'=>'minsk','parent'=>0]]],'collision_list'=>[],'ambiguous_list'=>[],'decision_required_list'=>[]]];$path=$store->write($snapshot);$run=$state->create();foreach([AreaMigrationStateStore::INSPECTED,AreaMigrationStateStore::SNAPSHOTTED,AreaMigrationStateStore::SIMULATED,AreaMigrationStateStore::READY]as $next)$run=$state->transition($run['run_id'],$next,$next===AreaMigrationStateStore::SNAPSHOTTED?['snapshot_path'=>$path]:[]);$lock->acquire($run['run_id']);return [$state,$lock,$journal,$run,new AreaMigrationExecutor($store,$state,$lock,$journal,new AreaMigrationRevalidator(),$injector)];}
    private function executor(AreaMigrationStateStore $state,AreaMigrationLock $lock,AreaMigrationJournal $journal): AreaMigrationExecutor {$run=array_values($GLOBALS['bml_test_options']['bml_area_migration_planning_runs'])[0];$store=new MigrationSnapshotStore(dirname((string)$run['snapshot_path']));return new AreaMigrationExecutor($store,$state,$lock,$journal,new AreaMigrationRevalidator());}
}
